export function getHuntPitsForMap(mapName: string | undefined): readonly HuntPitMarker[] {
    if (!mapName) {
        return [];
    }
    const key = mapName.replace(/\.amd$/i, '').toLowerCase();
    for (const [k, v] of Object.entries(HUNT_PITS_BY_MAP)) {
        if (k.toLowerCase() === key) {
            return v;
        }
    }
    return [];
}
